const HAZARD_ICONS  = { tornado:"🌪️", hail:"🌨️", wind:"💨" };
const HAZARD_LABELS = { tornado:"Tornadoes", hail:`Large Hail (≥1")`, wind:"Damaging Wind (≥58mph)" };
const AVAILABLE_YEARS = [2020,2021,2022,2023,2024,2025,2026];

function getYearData(state, year) {
  const yd = YEAR_DATA[String(year)];
  if (!yd) return { tornado:Array(12).fill(null), hail:Array(12).fill(null), wind:Array(12).fill(null) };
  const result = {};
  ["tornado","hail","wind"].forEach(type => {
    const raw = yd[type]?.[state] ?? Array(12).fill(0);
    result[type] = raw.map((v,m) => {
      const isFuture = year === CURRENT_YEAR && m > CURRENT_MONTH;
      return isFuture ? null : v;
    });
  });
  return result;
}

function getLTA(state, hazard) {
  return LTA_BASE[hazard]?.[state] ?? Array(12).fill(0);
}

function getCombinedYearData(states, year) {
  const result = {};
  ["tornado","hail","wind"].forEach(hz => {
    result[hz] = Array.from({length:12}, (_,m) => {
      if (year === CURRENT_YEAR && m > CURRENT_MONTH) return null;
      return Math.round(states.reduce((sum,s) => sum + (getYearData(s,year)[hz][m] ?? 0), 0) * 10) / 10;
    });
  });
  return result;
}

function getCombinedLTA(states, hazard) {
  return Array.from({length:12}, (_,m) =>
    Math.round(states.reduce((sum,s) => sum + (getLTA(s,hazard)[m] ?? 0), 0) * 10) / 10
  );
}

const fmt = v => (v === null || v === undefined) ? "—" : Number(v).toFixed(1);

function getDeparture(cur, lta) {
  if (cur === null || cur === undefined) return null;
  if (lta === 0) return cur > 0 ? 999 : 0;
  return ((cur - lta) / lta) * 100;
}

function getDepColor(pct) {
  if (pct === null) return "#333";
  if (pct > 100) return "#ff2d2d";
  if (pct > 50)  return "#ff6b2d";
  if (pct > 20)  return "#ffb347";
  if (pct < -50) return "#2dd4ff";
  if (pct < -20) return "#60afff";
  if (pct < 0)   return "#90cfff";
  return "#a3e635";
}

const HAZARD_PALETTE = {
  tornado: ["#7a0000","#a52020","#c94040","#7a3a10","#3a2a10","#141c2a"],
  hail:    ["#003a7a","#0a5299","#1a6ec4","#0a3a5a","#071c30","#08101a"],
  wind:    ["#1a4a00","#276b00","#3a8a10","#1a3a00","#0d1f00","#091208"],
};

function mapFill(state, hazard, months, stateYearData) {
  const data = stateYearData?.[hazard] ?? getLTA(state, hazard);
  const pal = HAZARD_PALETTE[hazard];
  if (months === "annual") {
    const v = data.reduce((a,b) => a + (b ?? 0), 0);
    if (v>20) return pal[0]; if (v>12) return pal[1]; if (v>6) return pal[2];
    if (v>3)  return pal[3]; if (v>1)  return pal[4];
  } else {
    const n = months.length;
    const v = months.reduce((a,m) => a + (data[m] ?? 0), 0);
    if (v > 4*n)   return pal[0]; if (v > 2*n)   return pal[1]; if (v > n)     return pal[2];
    if (v > 0.5*n) return pal[3]; if (v > 0.1*n) return pal[4];
  }
  return pal[5];
}

