const DATA_STATES = new Set(Object.keys(STATE_NAMES));

function USMap({ selStates, hov, onClickState, setHov, getFill }) {
  return (
    <div style={{position:"relative",width:"100%",paddingBottom:"62%"}}>
      <svg viewBox="0 0 975 610" style={{position:"absolute",top:0,left:0,width:"100%",height:"100%",cursor:"crosshair"}} preserveAspectRatio="xMidYMid meet">
        {Object.entries(STATE_PATHS).map(([abbr, {d, cx, cy}]) => {
          const isSel = selStates.has(abbr);
          const isHov = abbr === hov;
          const hasData = DATA_STATES.has(abbr);
          return (
            <g key={abbr}>
              <path
                d={d}
                fill={hasData ? getFill(abbr) : "#111"}
                stroke={isSel ? "#ff6b2d" : isHov ? "#66cc66" : "#2a3a4a"}
                strokeWidth={isSel ? 3 : isHov ? 1.5 : 0.7}
                style={{
                  transition:"fill 0.15s,stroke 0.15s",
                  cursor:hasData?"pointer":"default",
                  filter:isSel?"drop-shadow(0 0 5px #ff6b2d99)":"none"
                }}
                onClick={() => { if(hasData) onClickState(abbr); }}
                onMouseEnter={() => { if(hasData) setHov(abbr); }}
                onMouseLeave={() => setHov(null)}
              />
              {cx && cy && (
                <text x={cx} y={cy} textAnchor="middle" dominantBaseline="middle"
                  style={{
                    fontSize: isSel ? "9px" : "7px",
                    fill: isSel ? "#ffffff" : hasData ? "#99aaaa" : "#333",
                    fontWeight: isSel ? "900" : "400",
                    fontFamily: "monospace",
                    pointerEvents: "none",
                    userSelect: "none"
                  }}>
                  {abbr}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

function DepBar({ value, lta }) {
  const pct = getDeparture(value, lta);
  if (pct === null) return <div style={{color:"#333",fontSize:10}}>—</div>;
  const clamped = Math.max(-100, Math.min(200, pct));
  const w = Math.abs(clamped) / 2;
  const col = getDepColor(pct);
  return (
    <div style={{display:"flex",alignItems:"center",gap:7}}>
      <div style={{width:100,height:8,background:"#1a1a2e",borderRadius:4,position:"relative",overflow:"hidden"}}>
        <div style={{position:"absolute",left:pct>=0?"50%":`${50-w}%`,width:`${w}%`,height:"100%",background:col,borderRadius:3}} />
        <div style={{position:"absolute",left:"50%",top:0,bottom:0,width:1,background:"#444"}} />
      </div>
      <span style={{fontSize:10,color:col,fontWeight:700,minWidth:52,fontFamily:"monospace"}}>
        {pct > 900 ? "N/A" : `${pct>0?"+":""}${Math.round(pct)}%`}
      </span>
    </div>
  );
}

export default function App() {
  const [selStates, setSelStates] = useState(new Set(["OK"]));
  const [hov,       setHov]      = useState(null);

  const toggleState = (abbr) => setSelStates(prev => {
    const next = new Set(prev);
    if (next.has(abbr)) { if (next.size > 1) next.delete(abbr); }
    else next.add(abbr);
    return next;
  });
  const [selMonths, setSelMonths] = useState(new Set([CURRENT_MONTH > 0 ? CURRENT_MONTH - 1 : 0]));
  const [hazard,   setHazard]   = useState("tornado");
  const [view,     setView]     = useState("monthly");
  const [useMap,   setUseMap]   = useState(true);
  const [year,     setYear]     = useState(CURRENT_YEAR);

  // Keep a single "active" month for chart highlight and map coloring
  const selMonth = Math.max(...selMonths);

  const toggleMonth = (i) => {
    const isFuture = year === CURRENT_YEAR && i > CURRENT_MONTH;
    if (isFuture) return;
    setSelMonths(prev => {
      const next = new Set(prev);
      if (next.has(i)) {
        if (next.size === 1) return next; // always keep at least one
        next.delete(i);
      } else {
        next.add(i);
      }
      return next;
    });
    if (view === "annual") setView("monthly");
  };

  const ALL = Object.keys(STATE_NAMES).sort();
  const selArr = [...selStates].sort();
  const selLabel = selArr.length === 1
    ? STATE_NAMES[selArr[0]]
    : selArr.length <= 5 ? selArr.join(" · ") : `${selArr.length} States`;
  const curData = getCombinedYearData(selArr, year);
  const lta     = getCombinedLTA(selArr, hazard);
  const validCur = curData[hazard].filter(v => v !== null);
  const maxV = Math.max(...validCur, ...lta, 0.1) * 1.25;
  const allStatesYearData = Object.fromEntries(ALL.map(s => [s, getYearData(s, year)]));

  // Hero stats: sum across selected months only
  const selMonthsArr = Array.from(selMonths).sort((a,b) => a-b);
  const statCur = selMonthsArr.reduce((a, m) => a + (curData[hazard][m] ?? 0), 0);
  const statLta = selMonthsArr.reduce((a, m) => a + lta[m], 0);
  const statDep = getDeparture(statCur, statLta);
  const isFutureMonth = year === CURRENT_YEAR && selMonthsArr.some(m => m > CURRENT_MONTH);

  // Build a readable month range label e.g. "Mar", "Mar–May", "Mar, Jun, Aug"
  const monthRangeLabel = (() => {
    if (selMonthsArr.length === 1) return MONTHS[selMonthsArr[0]];
    // Check if contiguous
    const isContiguous = selMonthsArr.every((m,i) => i === 0 || m === selMonthsArr[i-1]+1);
    if (isContiguous) return `${MONTHS[selMonthsArr[0]]}–${MONTHS[selMonthsArr[selMonthsArr.length-1]]}`;
    return selMonthsArr.map(m => MONTHS[m]).join(", ");
  })();

  return (
    <div style={{minHeight:"100vh",background:"#06060f",color:"#e8e8f0",fontFamily:"'Courier New',monospace",overflow:"hidden"}}>
      <div style={{position:"fixed",inset:0,pointerEvents:"none",background:"radial-gradient(ellipse at 20% 50%,rgba(30,0,60,0.55) 0%,transparent 60%),radial-gradient(ellipse at 80% 20%,rgba(0,20,60,0.45) 0%,transparent 55%)"}} />
      <div style={{position:"fixed",inset:0,pointerEvents:"none",backgroundImage:"repeating-linear-gradient(0deg,transparent,transparent 39px,rgba(255,255,255,0.012) 40px),repeating-linear-gradient(90deg,transparent,transparent 39px,rgba(255,255,255,0.012) 40px)"}} />
      <div style={{position:"relative",maxWidth:1100,margin:"0 auto",padding:"18px 14px"}}>

        {/* Header */}
        <div style={{marginBottom:16}}>
          <div style={{display:"flex",alignItems:"baseline",gap:10,flexWrap:"wrap"}}>
            <h1 style={{fontSize:"clamp(18px,3vw,30px)",fontWeight:900,letterSpacing:"-0.03em",margin:0,fontFamily:"'Georgia',serif",background:"linear-gradient(135deg,#ff6b2d,#ffdf00,#fff)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>SEVERE CONVECTIVE</h1>
            <h1 style={{fontSize:"clamp(18px,3vw,30px)",fontWeight:900,letterSpacing:"-0.03em",margin:0,fontFamily:"'Georgia',serif",color:"#e8e8f0"}}>STORM ANALYZER</h1>
          </div>
          <p style={{color:"#888",fontSize:10,margin:"4px 0 0",letterSpacing:"0.1em"}}>REAL DATA · NOAA NCEI STORM EVENTS DATABASE · EVENTS PER 10,000 SQ MI</p>
        </div>

        {/* Controls */}
        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:14}}>
          <div style={{flex:"1 1 280px"}}>
            <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.15em",marginBottom:4}}>HAZARD TYPE</div>
            <div style={{display:"flex",gap:5}}>
              {["tornado","hail","wind"].map(h => (
                <button key={h} onClick={()=>setHazard(h)} style={{flex:1,padding:"8px 5px",background:hazard===h?(h==="tornado"?"#8b0000":h==="hail"?"#003a6b":"#1a3a00"):"#0d0d1a",border:`1px solid ${hazard===h?(h==="tornado"?"#ff4444":h==="hail"?"#4488ff":"#44aa44"):"#2a2a4a"}`,color:"#e8e8f0",fontSize:10,fontFamily:"inherit",cursor:"pointer",borderRadius:4,transition:"all 0.2s"}}>{HAZARD_ICONS[h]} {h.toUpperCase()}</button>
              ))}
            </div>
          </div>
          <div>
            <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.15em",marginBottom:4}}>YEAR</div>
            <select value={year} onChange={e=>{const y=Number(e.target.value);setYear(y);if(y===CURRENT_YEAR)setSelMonths(prev=>{const f=new Set([...prev].filter(m=>m<=CURRENT_MONTH));return f.size>0?f:new Set([CURRENT_MONTH]);});}} style={{background:"#0d0d1a",border:"1px solid #44aa44",color:"#88ee88",padding:"8px 12px",fontSize:12,fontFamily:"inherit",borderRadius:4,cursor:"pointer",outline:"none",fontWeight:700}}>
              {AVAILABLE_YEARS.map(y=><option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <div>
            <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.15em",marginBottom:4}}>CHART VIEW</div>
            <div style={{display:"flex",gap:5}}>
              {[["monthly","MONTHLY"],["annual","ANNUAL"]].map(([v,l])=>(
                <button key={v} onClick={()=>setView(v)} style={{padding:"8px 12px",background:view===v?"#1a1a3a":"#0d0d1a",border:`1px solid ${view===v?"#5555aa":"#2a2a4a"}`,color:view===v?"#8888ff":"#555",fontSize:10,fontFamily:"inherit",cursor:"pointer",borderRadius:4,transition:"all 0.2s"}}>{l}</button>
              ))}
            </div>
          </div>
          <div>
            <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.15em",marginBottom:4}}>SELECT STATE VIA</div>
            <div style={{display:"flex",gap:5}}>
              {[[true,"🗺 MAP"],[false,"▼ LIST"]].map(([v,l])=>(
                <button key={l} onClick={()=>setUseMap(v)} style={{padding:"8px 12px",background:useMap===v?"#0d2a0d":"#0d0d1a",border:`1px solid ${useMap===v?"#33aa33":"#2a2a4a"}`,color:useMap===v?"#55ee55":"#555",fontSize:10,fontFamily:"inherit",cursor:"pointer",borderRadius:4,transition:"all 0.2s"}}>{l}</button>
              ))}
            </div>
          </div>
        </div>

        {/* Month selector — multi-select */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.15em",marginBottom:4}}>
            MONTH SELECTION <span style={{color:"#777",fontWeight:400,textTransform:"none",letterSpacing:0}}>· click to toggle · multiple months sum together in stats above</span>
          </div>
          <div style={{display:"flex",gap:4,flexWrap:"wrap",alignItems:"center"}}>
            {MONTHS.map((m,i) => {
              const isFuture = year === CURRENT_YEAR && i > CURRENT_MONTH;
              const isSelected = selMonths.has(i);
              return (
                <button key={i} onClick={() => toggleMonth(i)}
                  style={{padding:"6px 10px",background:isSelected?"#2a1a00":"#0d0d1a",border:`1px solid ${isSelected?"#ff6b2d":isFuture?"#1a1a2a":"#2a2a4a"}`,color:isSelected?"#ff6b2d":isFuture?"#333":"#ccc",fontSize:10,fontFamily:"inherit",cursor:isFuture?"not-allowed":"pointer",borderRadius:4,transition:"all 0.15s",fontWeight:isSelected?700:400,minWidth:36,opacity:isFuture?0.4:1,boxShadow:isSelected?"0 0 6px #ff6b2d44":"none"}}>
                  {m}
                </button>
              );
            })}
            <button onClick={() => setSelMonths(new Set(MONTHS.map((_,i)=>i).filter(i=>!(year===CURRENT_YEAR&&i>CURRENT_MONTH))))}
              style={{padding:"6px 10px",background:"#0d0d1a",border:"1px solid #2a2a4a",color:"#888",fontSize:9,fontFamily:"inherit",cursor:"pointer",borderRadius:4,marginLeft:4}}>ALL</button>
            <button onClick={() => setSelMonths(new Set([selMonth]))}
              style={{padding:"6px 10px",background:"#0d0d1a",border:"1px solid #2a2a4a",color:"#888",fontSize:9,fontFamily:"inherit",cursor:"pointer",borderRadius:4}}>CLEAR</button>
            {year === CURRENT_YEAR && (
              <span style={{fontSize:9,color:"#888",fontStyle:"italic",marginLeft:8}}>
                Note: {CURRENT_YEAR} data is preliminary (SPC reports)
              </span>
            )}
          </div>
        </div>

        {/* State selector */}
        {!useMap ? (
          <div style={{marginBottom:14}}>
            <select value={selArr[0]} onChange={e=>setSelStates(new Set([e.target.value]))} style={{background:"#0d0d1a",border:"1px solid #2a2a4a",color:"#e8e8f0",padding:"9px 12px",fontSize:13,fontFamily:"inherit",borderRadius:4,cursor:"pointer",outline:"none",minWidth:260}}>
              {ALL.map(s=><option key={s} value={s}>{s} — {STATE_NAMES[s]}</option>)}
            </select>
          </div>
        ) : (
          <div style={{marginBottom:14,background:"#08080f",border:"1px solid #1e1e3a",borderRadius:8,padding:"10px 12px"}}>
            <div style={{fontSize:12,color:"#fff",letterSpacing:"0.12em",marginBottom:6}}>CLICK A STATE · {year} {view==="annual"?"ANNUAL":MONTHS[selMonth].toUpperCase()} · {HAZARD_ICONS[hazard]} {hazard.toUpperCase()}</div>
            <USMap
              selStates={selStates} hov={hov} onClickState={toggleState} setHov={setHov}
              getFill={(abbr) => mapFill(abbr,hazard,view==="annual"?"annual":selMonthsArr,allStatesYearData[abbr])}
            />
            <div style={{display:"flex",justifyContent:"space-between",flexWrap:"wrap",gap:8,marginTop:6}}>
              <div style={{fontSize:10,color:"#ccc",minHeight:16}}>
                {hov && !selStates.has(hov) && (()=>{
                  const hd = allStatesYearData[hov]?.[hazard];
                  const v  = view==="annual"
                    ? (hd ?? []).reduce((a,b)=>a+(b??0),0)
                    : (hd?.[selMonth] ?? null);
                  return <span><span style={{color:"#55ee55"}}>{hov}</span> — {STATE_NAMES[hov]} · {year} {view==="annual"?"Annual":MONTHS[selMonth]}: <span style={{color:"#ffb347"}}>{fmt(v)}</span></span>;
                })()}
              </div>
              <div style={{fontSize:10,color:"#ccc"}}><span style={{color:"#ff6b2d"}}>●</span> <strong style={{color:"#fff"}}>{selLabel}</strong></div>
            </div>
            <div style={{display:"flex",gap:10,marginTop:6,flexWrap:"wrap",alignItems:"center"}}>
              <span style={{fontSize:8,color:"#bbb",letterSpacing:"0.08em"}}>RISK SCALE:</span>
              {HAZARD_PALETTE[hazard].slice(0,5).map((c,i) => {
                const labels = view==="annual" ? [">20","12–20","6–12","3–6","1–3"] : [">4","2–4","1–2","0.5–1","0.1–0.5"];
                return <div key={i} style={{display:"flex",alignItems:"center",gap:3,fontSize:8,color:"#bbb"}}><div style={{width:9,height:9,background:c,border:"1px solid #333",borderRadius:2}}/> {labels[i]}</div>;
              })}
            </div>
          </div>
        )}

        {/* Hero Stats — reflect selected month(s) */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:12}}>
          {[
            {
              label:`${year} · ${monthRangeLabel}`,
              val: isFutureMonth ? "N/A" : fmt(statCur),
              sub:`${HAZARD_ICONS[hazard]} ${HAZARD_LABELS[hazard]} · events/10k sqmi`
            },
            {
              label:`LTA · ${monthRangeLabel}`,
              val: fmt(statLta),
              sub:`1991–2024 avg · ${selMonthsArr.length} month${selMonthsArr.length>1?"s":""}`
            },
            {
              label:"Departure",
              val: isFutureMonth?"N/A":statDep===null?"N/A":statDep>900?"N/A":`${statDep>0?"+":""}${Math.round(statDep)}%`,
              sub:`${selLabel} vs long-term avg`,
              hi:true
            }
          ].map((s,i)=>(
            <div key={i} style={{background:"#0d0d1a",border:`1px solid ${s.hi?"#ff6b2d44":"#1e1e3a"}`,borderRadius:6,padding:"12px 14px"}}>
              <div style={{fontSize:8,color:"#aaa",letterSpacing:"0.10em",marginBottom:5}}>{s.label}</div>
              <div style={{fontSize:"clamp(16px,2.5vw,26px)",fontWeight:900,color:s.hi?"#ff6b2d":"#e8e8f0",fontFamily:"'Georgia',serif",lineHeight:1}}>{s.val}</div>
              <div style={{fontSize:8,color:"#bbb",marginTop:4}}>{s.sub}</div>
            </div>
          ))}
        </div>

        {/* Banner */}
        <div style={{background:"#0a0a14",border:"1px solid #2a2a4a",borderRadius:5,padding:"8px 12px",marginBottom:12,display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          <span style={{fontSize:8,color:"#aaa",letterSpacing:"0.1em"}}>ANALYZING:</span>
          <span style={{fontSize:15,fontWeight:900,color:"#ff6b2d",fontFamily:"'Georgia',serif"}}>{selArr.length===1?selArr[0]:`${selArr.length} States`}</span>
          <span style={{fontSize:12,color:"#ddd"}}>{selLabel}</span>
          <span style={{fontSize:10,color:"#bbb",marginLeft:"auto"}}>{HAZARD_ICONS[hazard]} {HAZARD_LABELS[hazard]} · {MONTHS[selMonth]} {year}</span>
        </div>

        {view==="monthly" ? (
          <>
            <div style={{background:"#0a0a18",border:"1px solid #1e1e3a",borderRadius:8,padding:"16px",marginBottom:12}}>
              <div style={{fontSize:12,color:"#fff",letterSpacing:"0.12em",marginBottom:10}}>MONTHLY FREQUENCY — {selLabel} — {HAZARD_LABELS[hazard]}</div>
              <div style={{display:"flex",gap:14,marginBottom:10,flexWrap:"wrap"}}>
                {[{c:"#ff6b2d",l:`${year} (actual)`},{c:"#44cc44",dash:true,l:"LTA avg"}].map(x=>(
                  <div key={x.l} style={{display:"flex",alignItems:"center",gap:5,fontSize:9}}>
                    <div style={{width:16,height:3,background:x.dash?`repeating-linear-gradient(90deg,${x.c} 0,${x.c} 4px,transparent 4px,transparent 8px)`:x.c,borderRadius:2}}/><span style={{color:"#bbb"}}>{x.l}</span>
                  </div>
                ))}
              </div>
              <div style={{display:"flex",alignItems:"flex-end",gap:3,height:130,position:"relative"}}>
                {[0,0.25,0.5,0.75,1].map(p=>(
                  <div key={p} style={{position:"absolute",left:0,right:0,bottom:`${p*100}%`,borderTop:"1px dashed #181828",pointerEvents:"none"}}>
                    <span style={{fontSize:7,color:"#2a2a3a",position:"absolute",left:0,top:-8}}>{(maxV*p).toFixed(1)}</span>
                  </div>
                ))}
                {MONTHS.map((m,i) => {
                  const cur=curData[hazard][i], lt=lta[i];
                  const isSel=selMonths.has(i);
                  const isFuture = cur === null;
                  return (
                    <div key={i} onClick={()=>{if(!isFuture)toggleMonth(i)}}
                      style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",height:"100%",cursor:isFuture?"default":"pointer",position:"relative",background:isSel?"rgba(255,107,45,0.07)":"transparent",borderRadius:2,opacity:isFuture?0.3:1}}>
                      <div style={{flex:1,display:"flex",alignItems:"flex-end",width:"100%",justifyContent:"center"}}>
                        {!isFuture && <div style={{width:"40%",height:`${Math.max((cur/maxV)*100,0)}%`,background:isSel?"#ff6b2d":"#ff6b2d44",border:`1px solid ${isSel?"#ff6b2d99":"#ff6b2d33"}`,borderRadius:"2px 2px 0 0",transition:"height 0.4s"}}/>}
                        {isFuture && <div style={{width:"40%",height:"4px",background:"#1a1a2e",borderRadius:"2px 2px 0 0"}}/>}
                        <div style={{position:"absolute",bottom:`${(lt/maxV)*100}%`,left:"8%",right:"8%",height:2,background:isFuture?"#1a1a2e44":"#44cc44aa",borderRadius:1}}/>
                      </div>
                      <div style={{fontSize:7,color:isSel?"#ff6b2d":isFuture?"#2a2a3a":"#3a3a4a",marginTop:2}}>{m}</div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div style={{background:"#0d0d1a",border:"1px solid #2a2a4a",borderRadius:8,padding:"14px"}}>
              <div style={{fontSize:12,color:"#fff",letterSpacing:"0.12em",marginBottom:10}}>DETAIL — {monthRangeLabel.toUpperCase()} {year} — ALL HAZARDS · {selArr.length===1?selLabel:"MULTIPLE STATES"}</div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:10}}>
                {["tornado","hail","wind"].map(hz => {
                  const vals = selMonthsArr.map(m => curData[hz][m]);
                  const ltaVals = selMonthsArr.map(m => getCombinedLTA(selArr,hz)[m]);
                  const isFuture = vals.some(v => v === null);
                  const v = isFuture ? null : vals.reduce((a,b) => a+b, 0);
                  const l = ltaVals.reduce((a,b) => a+b, 0);
                  return (
                    <div key={hz} style={{background:"#080814",border:`1px solid ${hazard===hz?"#2a2a5a":"#141428"}`,borderRadius:5,padding:"10px 12px",opacity:isFuture?0.5:1}}>
                      <div style={{fontSize:10,color:"#777",marginBottom:7}}>{HAZARD_ICONS[hz]} {HAZARD_LABELS[hz]}</div>
                      {isFuture ? (
                        <div style={{fontSize:11,color:"#333",fontStyle:"italic",padding:"6px 0"}}>No data — future month</div>
                      ) : (
                        <>
                          <div style={{display:"flex",gap:12,marginBottom:7}}>
                            <div>
                              <div style={{fontSize:7,color:"#aaa",letterSpacing:"0.1em"}}>{year} · {monthRangeLabel}</div>
                              <div style={{fontSize:18,fontWeight:900,color:"#ff6b2d",fontFamily:"'Georgia',serif"}}>{fmt(v)}</div>
                            </div>
                            <div>
                              <div style={{fontSize:7,color:"#aaa",letterSpacing:"0.1em"}}>LTA</div>
                              <div style={{fontSize:18,fontWeight:900,color:"#4488ff",fontFamily:"'Georgia',serif"}}>{fmt(l)}</div>
                            </div>
                          </div>
                          <DepBar value={v} lta={l}/>
                        </>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </>
        ) : (
          <div style={{background:"#0a0a18",border:"1px solid #1e1e3a",borderRadius:8,padding:"16px"}}>
            <div style={{fontSize:12,color:"#fff",letterSpacing:"0.12em",marginBottom:12}}>ANNUAL SUMMARY — {selArr.length===1?selLabel:"MULTIPLE STATES"} — {year}</div>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
                <thead>
                  <tr>
                    <th style={{textAlign:"left",padding:"6px 8px",color:"#ccc",fontSize:8,letterSpacing:"0.1em",borderBottom:"1px solid #1e1e3a"}}>MONTH</th>
                    {["tornado","hail","wind"].map(h=>(
                      <th key={h} colSpan={3} style={{textAlign:"center",padding:"6px 8px",color:"#ccc",fontSize:8,borderBottom:"1px solid #1e1e3a"}}>{HAZARD_ICONS[h]} {h.toUpperCase()}</th>
                    ))}
                  </tr>
                  <tr>
                    <th style={{padding:"2px 8px",borderBottom:"1px solid #141428"}}/>
                    {["tornado","hail","wind"].map(h=>["ACT","LTA","DEP"].map(col=>(
                      <th key={h+col} style={{padding:"2px 6px",color:"#aaa",fontSize:7,letterSpacing:"0.1em",textAlign:"right",borderBottom:"1px solid #141428"}}>{col}</th>
                    )))}
                  </tr>
                </thead>
                <tbody>
                  {MONTHS.map((m,i) => {
                    const isFuture = year===CURRENT_YEAR && i>CURRENT_MONTH;
                    return (
                      <tr key={i} onClick={()=>{toggleMonth(i);setView("monthly");}}
                        style={{cursor:"pointer",background:selMonths.has(i)?"#1a1000":i%2?"#0d0d1a":"transparent",opacity:isFuture?0.35:1}}
                        onMouseEnter={e=>e.currentTarget.style.background="#1a1a2e"}
                        onMouseLeave={e=>e.currentTarget.style.background=i%2?"#0d0d1a":"transparent"}>
                        <td style={{padding:"5px 8px",color:"#ddd",fontWeight:700,fontSize:9}}>{m}</td>
                        {["tornado","hail","wind"].map(h => {
                          const v = curData[h][i];
                          const l = getCombinedLTA(selArr,h)[i];
                          const d = getDeparture(v,l);
                          const col = getDepColor(d);
                          return [
                            <td key={h+"v"} style={{padding:"5px 6px",textAlign:"right",color:v===null?"#2a2a3a":"#e8e8f0"}}>{fmt(v)}</td>,
                            <td key={h+"l"} style={{padding:"5px 6px",textAlign:"right",color:"#4488ff"}}>{fmt(l)}</td>,
                            <td key={h+"d"} style={{padding:"5px 6px",textAlign:"right",fontWeight:700,color:col}}>{d===null?"—":d>900?"N/A":`${d>0?"+":""}${Math.round(d)}%`}</td>
                          ];
                        })}
                      </tr>
                    );
                  })}
                  <tr style={{borderTop:"1px solid #2a2a4a"}}>
                    <td style={{padding:"7px 8px",color:"#e8e8f0",fontWeight:900,fontSize:9}}>TOTAL</td>
                    {["tornado","hail","wind"].map(h => {
                      const vals = curData[h];
                      const tot  = vals.reduce((a,b)=>a+(b??0),0);
                      const avail= vals.filter(v=>v!==null).length;
                      const lt   = getCombinedLTA(selArr,h).slice(0,avail).reduce((a,b)=>a+b,0);
                      const d    = getDeparture(tot,lt);
                      const col  = getDepColor(d);
                      return [
                        <td key={h+"v"} style={{padding:"7px 6px",textAlign:"right",color:"#ff6b2d",fontWeight:700}}>{fmt(tot)}</td>,
                        <td key={h+"l"} style={{padding:"7px 6px",textAlign:"right",color:"#4488ff",fontWeight:700}}>{fmt(lt)}</td>,
                        <td key={h+"d"} style={{padding:"7px 6px",textAlign:"right",fontWeight:900,color:col}}>{d===null?"—":d>900?"N/A":`${d>0?"+":""}${Math.round(d)}%`}</td>
                      ];
                    })}
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Departure legend */}
        <div style={{marginTop:12,display:"flex",gap:14,flexWrap:"wrap"}}>
          {[["#ff2d2d",">+100%"],["#ff6b2d","+50–100%"],["#ffb347","+20–50%"],["#a3e635","Near normal"],["#90cfff","0–20% below"],["#60afff","20–50% below"],["#2dd4ff",">50% below"]].map(([c,l])=>(
            <div key={l} style={{display:"flex",alignItems:"center",gap:4,fontSize:8,color:"#ccc"}}>
              <div style={{width:6,height:6,borderRadius:"50%",background:c}}/> {l}
            </div>
          ))}
        </div>

        <div style={{marginTop:10,fontSize:8,color:"#555",lineHeight:1.7}}>
          SOURCE: NOAA NCEI Storm Events Database · Events normalized to per 10,000 sq mi · LTA computed from 1991–2024 (34 years) · 48 contiguous states
        </div>
      </div>
      <style>{`select option{background:#0d0d1a}*{box-sizing:border-box}::-webkit-scrollbar{width:5px;height:5px}::-webkit-scrollbar-track{background:#0d0d1a}::-webkit-scrollbar-thumb{background:#2a2a4a;border-radius:3px}`}</style>
    </div>
  );
}
